package com.bank.topk;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Returns the K most frequent transaction types two ways.
public class TopKFrequentService {

    private static final Logger log = Logger.getLogger(TopKFrequentService.class.getName());

    private Map<String, Integer> frequency(String[] types) {
        Map<String, Integer> freq = new HashMap<>();
        for (String t : types) {
            freq.merge(t, 1, Integer::sum);
        }
        return freq;
    }

    // Min-heap of size K by frequency. O(n log K).
    public List<String> byHeap(String[] types, int k) {
        Map<String, Integer> freq = frequency(types);
        PriorityQueue<Map.Entry<String, Integer>> heap =
                new PriorityQueue<>((a, b) -> a.getValue() - b.getValue());
        for (Map.Entry<String, Integer> e : freq.entrySet()) {
            heap.offer(e);
            if (heap.size() > k) heap.poll(); // drop least frequent
        }
        List<String> result = new ArrayList<>();
        while (!heap.isEmpty()) result.add(heap.poll().getKey());
        log.info("Top " + k + " (heap) -> " + result);
        return result;
    }

    // Frequency-indexed bucket sort. O(n).
    public List<String> byBucket(String[] types, int k) {
        Map<String, Integer> freq = frequency(types);
        List<String>[] buckets = new List[types.length + 1];
        for (Map.Entry<String, Integer> e : freq.entrySet()) {
            int f = e.getValue();
            if (buckets[f] == null) buckets[f] = new ArrayList<>();
            buckets[f].add(e.getKey());
        }
        List<String> result = new ArrayList<>();
        for (int f = buckets.length - 1; f >= 0 && result.size() < k; f--) {
            if (buckets[f] != null) {
                for (String t : buckets[f]) {
                    if (result.size() == k) break;
                    result.add(t);
                }
            }
        }
        log.info("Top " + k + " (bucket) -> " + result);
        return result;
    }
}
