package com.bank.topk;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class TopKDemo {

    private static final Logger log = Logger.getLogger(TopKDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Top K Transaction Types");
        String[] types = {
            "UPI","UPI","NEFT","UPI","ATM","NEFT","UPI","IMPS","ATM","UPI"
        };
        int k = 2; // top 2 types

        TopKFrequentService service = new TopKFrequentService();
        service.byHeap(types, k);
        service.byBucket(types, k);
    }
}
